mapper.sql:
WHERE 1 = 1

    AND p.account_user_id = #{patientAccountUserId}


    AND c.assigned_doctor_id = #{doctorId}


    AND c.status != 'DELETED'


    AND (
        c.case_no LIKE CONCAT('%', #{query.keyword}, '%')
        OR p.patient_no LIKE CONCAT('%', #{query.keyword}, '%')
        OR p.legacy_patient_code LIKE CONCAT('%', #{query.keyword}, '%')
    )


    AND c.status = #{query.status}


    AND c.eye_side = #{query.eyeSide}

mapper.select:
SELECT c.id AS id, c.case_no AS caseNo, c.patient_id AS patientId, p.patient_no AS patientNo, c.patient_code AS patientCode, c.patient_age AS patientAge, c.patient_gender AS patientGender, c.eye_side AS eyeSide, c.status AS status, c.workflow_status AS workflowStatus, c.diagnosis_note AS diagnosisNote, c.created_by AS createdBy, u.real_name AS createdByName, c.assigned_doctor_id AS assignedDoctorId, d.real_name AS assignedDoctorName, d.professional_no AS assignedDoctorProfessionalNo, c.created_at AS createdAt, c.updated_at AS updatedAt FROM medical_case c JOIN patient_profile p ON p.id = c.patient_id LEFT JOIN sys_user u ON u.id = c.created_by LEFT JOIN sys_user d ON d.id = c.assigned_doctor_id WHERE c.assigned_doctor_id = #{doctorId} AND c.status != 'DELETED' AND ( c.case_no = #{reference} OR p.patient_no = #{reference} OR p.legacy_patient_code = #{reference}
OR c.id = #{numericId}
) LIMIT 1
